def _validate_request_data(data):
    """Validate the shape of an incoming request payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data):
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Process an incoming API request payload.

    Args:
        data: The request payload. Unless ``legacy_mode`` is enabled, this
            must be a dictionary whose keys are strings.
        legacy_mode: If true, bypass payload validation for older clients.

    Raises:
        TypeError: If validation is enabled and ``data`` is not a dictionary,
            or if it contains a non-string key.
    """
    if not legacy_mode:
        _validate_request_data(data)

    return process(data)

